import type { Metadata } from "next";
import "./globals.css";
import { ThirdPartyScripts } from "@/components/ThirdPartyScripts";
import { CursorGlow } from "@/components/CursorGlow";

/**
 * Root layout — Generated by the Webflow Cloner agent.
 * <html lang> + <body class> mirror the original so global CSS keys
 * off the same selectors; favicons + site metadata come from the
 * captured <head>.
 */
/**
 * Resolves relative metadata URLs (og:image, twitter:image) to absolute ones —
 * social scrapers require absolute URLs. Set NEXT_PUBLIC_SITE_URL to the
 * production domain of THIS deployment (defaults to the cloned site's origin).
 */
const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL ?? "https://www.mycroft.io";

/* No site-wide title/description defaults: every page defines its own
   metadata, and the original site has none on pages like /terms and
   /thank-you — a layout default would leak onto them. */
export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: "Mycroft",
  icons: {
    icon: [{ url: "/icons/32x32.png", type: "image/x-icon" }],
    apple: [{ url: "/icons/256x256.png" }],
  },
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>
        {children}
        <CursorGlow />
        <ThirdPartyScripts />
      </body>
    </html>
  );
}
